BEGIN;
CREATE TABLE "OperatingBankReceipt" (
 id text PRIMARY KEY DEFAULT gen_random_uuid()::text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,
 "orderId" text NOT NULL REFERENCES "TradeOrder"(id),kind text NOT NULL CHECK(kind IN ('PAYMENT','REFUND')),"refundId" text REFERENCES "Refund"(id),amount bigint NOT NULL CHECK(amount>0),"transferredAt" timestamptz NOT NULL,"bankTransferId" text NOT NULL,"proofAssetId" text NOT NULL REFERENCES "MediaAsset"(id),"requestKey" text NOT NULL,"proposerId" text NOT NULL REFERENCES "User"(id),"reviewerId" text REFERENCES "User"(id),"reviewedAt" timestamptz,
 state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','VERIFIED','REJECTED')),note text NOT NULL,"reviewNote" text,"paymentId" text UNIQUE REFERENCES "PaymentTransaction"(id),"refundTransactionId" text UNIQUE REFERENCES "RefundTransaction"(id),UNIQUE("proposerId","requestKey"),CHECK((kind='PAYMENT' AND "refundId" IS NULL) OR (kind='REFUND' AND "refundId" IS NOT NULL)));
CREATE UNIQUE INDEX "OperatingBankReceipt_active_transfer" ON "OperatingBankReceipt"("bankTransferId") WHERE state IN ('PENDING','VERIFIED');
CREATE INDEX "OperatingBankReceipt_orderId_createdAt_idx" ON "OperatingBankReceipt"("orderId","createdAt");
CREATE TABLE "OperatingFulfilment" (
 id text PRIMARY KEY DEFAULT gen_random_uuid()::text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,"serviceId" text NOT NULL REFERENCES "OperatingService"(id),"deliveredAt" timestamptz NOT NULL,"proofAssetId" text NOT NULL REFERENCES "MediaAsset"(id),note text NOT NULL,"requestKey" text NOT NULL,"proposerId" text NOT NULL REFERENCES "User"(id),"reviewerId" text REFERENCES "User"(id),"reviewedAt" timestamptz,state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','APPROVED','REJECTED')),"reviewNote" text,UNIQUE("serviceId","requestKey"));
ALTER TABLE "AdCampaign" ADD COLUMN "creativeTitle" text NOT NULL DEFAULT '',ADD COLUMN "creativeSummary" text NOT NULL DEFAULT '',ADD COLUMN "creatorId" text REFERENCES "User"(id),ADD COLUMN "reviewerId" text REFERENCES "User"(id),ADD COLUMN "reviewedAt" timestamptz,ADD COLUMN "reviewNote" text;
INSERT INTO "AdPlacement"(code,surface,format,label,active) VALUES ('academy-home-sponsored','HOME','IMAGE_TEXT','广告',false),('academy-article-sponsored','ARTICLE_FOOTER','IMAGE_TEXT','广告',false),('academy-media-sponsored','MEDIA_FOOTER','IMAGE_TEXT','广告',false),('academy-teacher-sponsored','TEACHER_LIST','IMAGE_TEXT','广告',false) ON CONFLICT(code) DO NOTHING;
INSERT INTO "FinanceAccount"(code,title,kind) VALUES ('OPERATING_BANK_CLEARING','运营服务核验银行收付','ASSET'),('OPERATING_DEFERRED','运营服务待履约预收','LIABILITY'),('OPERATING_REVENUE','运营服务实际履约收入','REVENUE'),('OPERATING_REFUND_PAYABLE','运营服务异常收款待返还','LIABILITY') ON CONFLICT(code) DO NOTHING;
COMMIT;
